PRAGMA foreign_keys = ON;
CREATE TABLE app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO app_meta VALUES('currency_scale','100');
CREATE TABLE students (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE user (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,emailVerified INTEGER DEFAULT 0,image TEXT,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('admin','staff','student')),createdAt INTEGER NOT NULL DEFAULT 1,updatedAt INTEGER NOT NULL DEFAULT 1);
CREATE TABLE session (id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,token TEXT NOT NULL UNIQUE,expiresAt INTEGER NOT NULL,ipAddress TEXT,userAgent TEXT,createdAt INTEGER NOT NULL DEFAULT 1,updatedAt INTEGER NOT NULL DEFAULT 1);
CREATE TABLE account (id TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE,accountId TEXT NOT NULL,providerId TEXT NOT NULL,accessToken TEXT,refreshToken TEXT,accessTokenExpiresAt INTEGER,refreshTokenExpiresAt INTEGER,expiresAt INTEGER,scope TEXT,idToken TEXT,password TEXT,createdAt INTEGER NOT NULL DEFAULT 1,updatedAt INTEGER NOT NULL DEFAULT 1);
CREATE TABLE verification (id TEXT PRIMARY KEY,identifier TEXT NOT NULL,value TEXT NOT NULL,expiresAt INTEGER NOT NULL,createdAt INTEGER NOT NULL DEFAULT 1,updatedAt INTEGER NOT NULL DEFAULT 1);
CREATE TABLE user_student_links (user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE,student_id INTEGER NOT NULL UNIQUE REFERENCES students(id) ON DELETE RESTRICT);
CREATE TABLE cards (card_uid TEXT PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'active',issued_at TEXT NOT NULL DEFAULT '2026-01-01');
CREATE TABLE accounts (student_id INTEGER PRIMARY KEY REFERENCES students(id) ON DELETE CASCADE,balance INTEGER NOT NULL DEFAULT 0,max_overdraft_week INTEGER NOT NULL DEFAULT 0);
CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT,card_uid TEXT,type TEXT NOT NULL CHECK(type IN ('TOPUP','DEBIT','ADJUST')),amount INTEGER NOT NULL,overdraft_component INTEGER NOT NULL DEFAULT 0,payment_method TEXT,description TEXT,staff TEXT,created_at TEXT NOT NULL DEFAULT '2026-01-01');
CREATE TABLE transaction_note_history (id INTEGER PRIMARY KEY AUTOINCREMENT,transaction_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,previous_description TEXT,new_description TEXT,edited_by TEXT,edited_at TEXT NOT NULL DEFAULT '2026-01-01');
CREATE TABLE overdraft_weeks (student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT,week_start_utc TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(student_id,week_start_utc));
CREATE TABLE wechat_topup_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT,requested_amount INTEGER NOT NULL,payable_amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','expired','cancelled')),created_by_user_id TEXT NOT NULL,created_by_name TEXT,internal_note TEXT,review_note TEXT,reviewed_by_user_id TEXT,reviewed_by_name TEXT,approved_transaction_id INTEGER REFERENCES transactions(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT '2026-01-01',expires_at TEXT NOT NULL,claimed_at TEXT,reviewed_at TEXT);
CREATE INDEX idx_tx_student_time ON transactions(student_id,created_at);
CREATE INDEX idx_transactions_student_id_created_at ON transactions(student_id,created_at DESC);
CREATE INDEX custom_student_cards ON cards(student_id,status);
CREATE INDEX custom_user_name ON user(name);
CREATE TABLE audit (message TEXT NOT NULL);
CREATE TRIGGER custom_user_updated AFTER UPDATE OF name ON user BEGIN INSERT INTO audit VALUES(NEW.name); END;
CREATE TRIGGER custom_customer_audit AFTER UPDATE OF name ON students BEGIN INSERT INTO audit VALUES(NEW.name); END;
